  uint32_t rotated = (e << 30) | (e >> 2);
  r.u32[3] = rotated + ub.u32[3];
  r.u32[2] = ub.u32[2];
  r.u32[1] = ub.u32[1];
  r.u32[0] = ub.u32[0];
  return fio___fx86_from_u128(r);
#endif
