      ctr3 = _mm_xor_si128(ctr3, rk[0]);
      ctr4 = _mm_xor_si128(ctr4, rk[0]);
      ctr5 = _mm_xor_si128(ctr5, rk[0]);
      ctr6 = _mm_xor_si128(ctr6, rk[0]);
