/* Distinguished Name Attributes */
#define FIO_X509_OID_COMMON_NAME \
  ((fio_u128){.u8 = {0x55, 0x04, 0x03, [15] = 3}}) /* 2.5.4.3 */
#define FIO_X509_OID_COUNTRY \
