#undef FIO___LYRA2_BLOCK_LEN_BYTES
#undef FIO___LYRA2_BLAKE2_SAFE_INT64
#undef FIO___LYRA2_BLAKE2_SAFE_BYTES
#undef FIO___LYRA2_ROW_LEN_INT64
#undef FIO___LYRA2_ROW_LEN_BYTES
#undef FIO___LYRA2_ROW

